			"[data-context-menu][data-menu-material='translucent']",
			"[data-trigger-menu][data-menu-material='translucent']",
			"[data-document-zoom-controls]",
			"div:has(> [data-quote-popover])",
			"div:has(> [data-changes-hover-preview='true'])",
